export interface CalChartShwPosition {
  x: number;
  y: number;
}

export interface CalChartShwPoint extends CalChartShwPosition {
  symbol: number;
  references: CalChartShwPosition[];
}

export interface CalChartShwMovement {
  type: "even" | "mark";
  beats: number;
  beats_per_step?: number;
  facing: number;
  x?: number;
  y?: number;
  x1?: number;
  y1?: number;
  x2?: number;
  y2?: number;
}

export interface CalChartShwSheet {
  label: string;
  beats: number;
  positions: CalChartShwPoint[];
  continuities: Map<number, string>;
}

export interface CalChartShwShow {
  version: string;
  labels: string[];
  sheets: CalChartShwSheet[];
}

interface CalChartBlock {
  tag: string;
  start: number;
  size: number;
}

const decoder = new TextDecoder();

function readTag(data: Uint8Array, offset: number): string {
  return decoder.decode(data.subarray(offset, offset + 4));
}

function readUint32(view: DataView, offset: number): number {
  return view.getUint32(offset, false);
}

function parseBlocks(data: Uint8Array, view: DataView, start: number, length: number): CalChartBlock[] {
  const blocks: CalChartBlock[] = [];
  const end = start + length;
  let offset = start;
  while (offset < end) {
    if (offset + 16 > end) throw new Error("Truncated CalChart block header");
    const tag = readTag(data, offset);
    const size = readUint32(view, offset + 4);
    const payloadStart = offset + 8;
    const payloadEnd = payloadStart + size;
    if (payloadEnd + 8 > end || readTag(data, payloadEnd) !== "END " || readTag(data, payloadEnd + 4) !== tag) {
      throw new Error(`Invalid CalChart ${tag} block`);
    }
    blocks.push({ tag, start: payloadStart, size });
    offset = payloadEnd + 8;
  }
  return blocks;
}

function requiredBlock(blocks: CalChartBlock[], tag: string, context: string): CalChartBlock {
  const block = blocks.find(candidate => candidate.tag === tag);
  if (!block) throw new Error(`CalChart ${context} has no ${tag} block`);
  return block;
}

function readString(data: Uint8Array, start: number, size: number): string {
  const end = data.indexOf(0, start);
  if (end < start || end >= start + size) throw new Error("CalChart string is not null-terminated");
  return decoder.decode(data.subarray(start, end));
}

function readLabels(data: Uint8Array, block: CalChartBlock, count: number): string[] {
  const labels: string[] = [];
  const end = block.start + block.size;
  let offset = block.start;
  while (offset < end && labels.length < count) {
    const terminator = data.indexOf(0, offset);
    if (terminator < offset || terminator >= end) throw new Error("Invalid CalChart marcher labels");
    labels.push(decoder.decode(data.subarray(offset, terminator)) || String(labels.length + 1));
    offset = terminator + 1;
  }
  if (labels.length !== count || offset !== end) throw new Error(`CalChart file declares ${count} marchers but has ${labels.length} labels`);
  return labels;
}

function readPositions(data: Uint8Array, view: DataView, block: CalChartBlock, count: number): CalChartShwPoint[] {
  const positions: CalChartShwPoint[] = [];
  const end = block.start + block.size;
  let offset = block.start;
  while (offset < end && positions.length < count) {
    const size = data[offset];
    const recordStart = offset + 1;
    const recordEnd = recordStart + size;
    if (size < 7 || recordEnd > end) throw new Error(`Invalid CalChart point ${positions.length + 1}`);
    const position = { x: view.getInt16(recordStart, false), y: view.getInt16(recordStart + 2, false) };
    const references = [position, position, position].map(value => ({ ...value }));
    const referenceCount = data[recordStart + 4];
    let fieldOffset = recordStart + 5;
    for (let referenceIndex = 0; referenceIndex < referenceCount; referenceIndex += 1) {
      if (fieldOffset + 5 > recordEnd) throw new Error(`Invalid CalChart point ${positions.length + 1} reference`);
      const reference = data[fieldOffset];
      if (reference < 1 || reference > 3) throw new Error(`Invalid CalChart reference point ${reference}`);
      references[reference - 1] = { x: view.getInt16(fieldOffset + 1, false), y: view.getInt16(fieldOffset + 3, false) };
      fieldOffset += 5;
    }
    if (fieldOffset + 2 !== recordEnd) throw new Error(`Invalid CalChart point ${positions.length + 1} fields`);
    positions.push({ ...position, references, symbol: data[fieldOffset] });
    offset = recordEnd;
  }
  if (positions.length !== count || offset !== end) throw new Error(`CalChart sheet has ${positions.length} points, expected ${count}`);
  return positions;
}

function readContinuities(data: Uint8Array, view: DataView, block: CalChartBlock | undefined): Map<number, string> {
  const continuities = new Map<number, string>();
  if (!block) return continuities;
  for (const entry of parseBlocks(data, view, block.start, block.size)) {
    if (entry.tag !== "ECNT" || entry.size < 2) continue;
    const text = readString(data, entry.start + 1, entry.size - 1);
    continuities.set(data[entry.start], text);
  }
  return continuities;
}

function viewerPosition(position: CalChartShwPosition): CalChartShwPosition {
  return { x: position.x / 16 + 80, y: position.y / 16 + 42 };
}

function facing(from: CalChartShwPosition, to: CalChartShwPosition): number {
  if (from.x === to.x && from.y === to.y) return 0;
  return (Math.atan2(-(to.x - from.x), to.y - from.y) * 180 / Math.PI + 360) % 360;
}

function directionFacing(direction: string): number {
  const directions: Record<string, number> = { n: 270, nw: 315, w: 0, sw: 45, s: 90, se: 135, e: 180, ne: 225 };
  const result = directions[direction.toLowerCase()];
  if (result === undefined) throw new Error(`Unsupported CalChart direction ${direction}`);
  return result;
}

function directionVector(direction: string): CalChartShwPosition {
  const vectors: Record<string, CalChartShwPosition> = {
    n: { x: 1, y: 0 }, nw: { x: 1, y: -1 }, w: { x: 0, y: -1 }, sw: { x: -1, y: -1 },
    s: { x: -1, y: 0 }, se: { x: -1, y: 1 }, e: { x: 0, y: 1 }, ne: { x: 1, y: 1 },
  };
  const result = vectors[direction.toLowerCase()];
  if (!result) throw new Error(`Unsupported CalChart direction ${direction}`);
  return result;
}

function splitDmHs(from: CalChartShwPosition, to: CalChartShwPosition, diagonalFirst: boolean): CalChartShwPosition[] {
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  let highStep: CalChartShwPosition;
  let diagonal: CalChartShwPosition;
  if (Math.abs(dx) > Math.abs(dy)) {
    highStep = { x: ((dx < 0) !== (dy < 0)) ? dx + dy : dx - dy, y: 0 };
    diagonal = { x: ((dx < 0) !== (dy < 0)) ? -dy : dy, y: dy };
  } else {
    highStep = { x: 0, y: ((dx < 0) !== (dy < 0)) ? dy + dx : dy - dx };
    diagonal = { x: dx, y: ((dx < 0) !== (dy < 0)) ? -dx : dx };
  }
  const vectors = diagonalFirst ? [diagonal, highStep] : [highStep, diagonal];
  const points: CalChartShwPosition[] = [];
  let current = from;
  for (const vector of vectors) {
    if (vector.x === 0 && vector.y === 0) continue;
    current = { x: current.x + vector.x, y: current.y + vector.y };
    points.push(current);
  }
  return points;
}

export function compileCalChartShwMovements(show: CalChartShwShow, sheetIndex: number, marcherIndex: number): CalChartShwMovement[] {
  const sheet = show.sheets[sheetIndex];
  const point = sheet.positions[marcherIndex];
  const next = show.sheets[sheetIndex + 1]?.positions[marcherIndex] ?? point;
  const text = sheet.continuities.get(point.symbol) ?? (sheetIndex + 1 === show.sheets.length ? "mtrm e" : "even rem np");
  const movements: CalChartShwMovement[] = [];
  let current: CalChartShwPosition = point;
  let beatsRemaining = sheet.beats;

  const appendMove = (destination: CalChartShwPosition, beats: number): void => {
    if (beats <= 0 || beatsRemaining <= 0 || (current.x === destination.x && current.y === destination.y)) return;
    const actualBeats = Math.min(beats, beatsRemaining);
    const fromViewer = viewerPosition(current);
    const toViewer = viewerPosition(destination);
    movements.push({ type: "even", beats: actualBeats, beats_per_step: 1, x1: fromViewer.x, y1: fromViewer.y, x2: toViewer.x, y2: toViewer.y, facing: facing(fromViewer, toViewer) });
    current = destination;
    beatsRemaining -= actualBeats;
  };
  const appendMark = (beats: number, direction: string): void => {
    const actualBeats = Math.min(Math.abs(Math.trunc(beats)), beatsRemaining);
    if (actualBeats <= 0) return;
    const position = viewerPosition(current);
    movements.push({ type: "mark", beats: actualBeats, x: position.x, y: position.y, facing: directionFacing(direction) });
    beatsRemaining -= actualBeats;
  };
  const resolvePoint = (token: string): CalChartShwPosition => {
    if (token.toLowerCase() === "np") return next;
    const match = /^r([1-3])$/i.exec(token);
    if (!match) throw new Error(`Unsupported CalChart point ${token}`);
    return point.references[Number(match[1]) - 1];
  };

  for (const line of text.split(/\r?\n/).map(value => value.trim()).filter(Boolean)) {
    let match: RegExpExecArray | null;
    if ((match = /^mt\s+(\d+)\s+(\w+)$/i.exec(line))) appendMark(Number(match[1]), match[2]);
    else if ((match = /^mt\s+step\(\s*(\d+)\s+(\d+)\s+(r[1-3])\s*\)\s+(\w+)$/i.exec(line))) {
      const destination = resolvePoint(match[3]);
      const dmMagnitude = Math.abs(destination.x - current.x) === Math.abs(destination.y - current.y)
        ? Math.abs(destination.x - current.x) / 16
        : Math.hypot(destination.x - current.x, destination.y - current.y) / 16;
      appendMark(dmMagnitude * Number(match[1]) / Number(match[2]), match[4]);
    } else if ((match = /^mtrm\s+(\w+)$/i.exec(line))) appendMark(beatsRemaining, match[1]);
    else if ((match = /^(nsew|ewns)\s+(np|r[1-3])$/i.exec(line))) {
      const destination = resolvePoint(match[2]);
      const corner = match[1].toLowerCase() === "nsew" ? { x: destination.x, y: current.y } : { x: current.x, y: destination.y };
      appendMove(corner, Math.abs((corner.x - current.x) || (corner.y - current.y)) / 16);
      appendMove(destination, Math.abs((destination.x - current.x) || (destination.y - current.y)) / 16);
    } else if ((match = /^(dmhs|hsdm)\s+(np|r[1-3])$/i.exec(line))) {
      const destination = resolvePoint(match[2]);
      for (const segmentEnd of splitDmHs(current, destination, match[1].toLowerCase() === "dmhs")) {
        appendMove(segmentEnd, Math.abs((segmentEnd.x - current.x) || (segmentEnd.y - current.y)) / 16);
      }
    } else if ((match = /^fm\s+(\d+)\s+(\w+)$/i.exec(line))) {
      const beats = Number(match[1]);
      const vector = directionVector(match[2]);
      appendMove({ x: current.x + vector.x * beats * 16, y: current.y + vector.y * beats * 16 }, beats);
    } else if ((match = /^even\s+(rem|\d+)\s+(np|r[1-3])$/i.exec(line))) {
      appendMove(resolvePoint(match[2]), match[1].toLowerCase() === "rem" ? beatsRemaining : Number(match[1]));
    } else throw new Error(`Unsupported CalChart continuity on sheet ${sheetIndex + 1}: ${line}`);
  }
  if (beatsRemaining > 0) appendMark(beatsRemaining, "e");
  return movements;
}

export function parseCalChartShw(buffer: ArrayBuffer): CalChartShwShow {
  const data = new Uint8Array(buffer);
  const view = new DataView(buffer);
  if (data.length < 24 || readTag(data, 0) !== "INGL" || readTag(data, 4).slice(0, 2) !== "GU") {
    throw new Error("This is not a CalChart .shw file");
  }
  const major = Number.parseInt(String.fromCharCode(data[6]), 10);
  const minor = Number.parseInt(String.fromCharCode(data[7]), 10);
  if (!Number.isFinite(major) || !Number.isFinite(minor) || major < 3 || (major === 3 && minor < 4)) {
    throw new Error("ChartXR supports CalChart .shw version 3.4 or newer");
  }
  const rootBlocks = parseBlocks(data, view, 8, data.length - 8);
  const showBlock = requiredBlock(rootBlocks, "SHOW", "file");
  const showBlocks = parseBlocks(data, view, showBlock.start, showBlock.size);
  const sizeBlock = requiredBlock(showBlocks, "SIZE", "show");
  if (sizeBlock.size !== 4) throw new Error("Invalid CalChart marcher count");
  const marcherCount = readUint32(view, sizeBlock.start);
  if (marcherCount === 0) throw new Error("CalChart show has no marchers");
  const labels = readLabels(data, requiredBlock(showBlocks, "LABL", "show"), marcherCount);
  const sheets = showBlocks.filter(block => block.tag === "SHET").map((sheetBlock, index): CalChartShwSheet => {
    const blocks = parseBlocks(data, view, sheetBlock.start, sheetBlock.size);
    const nameBlock = requiredBlock(blocks, "NAME", `sheet ${index + 1}`);
    const durationBlock = requiredBlock(blocks, "DURA", `sheet ${index + 1}`);
    if (durationBlock.size !== 4) throw new Error(`Invalid CalChart sheet ${index + 1} duration`);
    return {
      label: readString(data, nameBlock.start, nameBlock.size) || String(index + 1),
      beats: readUint32(view, durationBlock.start),
      positions: readPositions(data, view, requiredBlock(blocks, "PNTS", `sheet ${index + 1}`), marcherCount),
      continuities: readContinuities(data, view, blocks.find(block => block.tag === "CONT")),
    };
  });
  if (sheets.length === 0) throw new Error("CalChart show has no sheets");
  return { version: `${major}.${minor}`, labels, sheets };
}